1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		planID      string
20		terms       PlanTerms
21		activatedAt time.Time
22		// termsHistory 按生效月份升序记录每次换套餐后的条件；
23		// 首条为开通当月适用的开通快照。账单按账期从中取当时适用的条件。
24		termsHistory []termsEntry
25		// pending 尚未生效的换套餐安排，每账户至多一条；nil 表示无安排。
26		pending *PlanChange
27		// cancelEnd 已安排的终止时刻（取消请求时刻的下一个 UTC 自然月月初）。
28		// 非 nil 且尚未到达时为等待取消状态；到达后本订阅段终止并移入 history。
29		cancelEnd *time.Time
30		// endedAt 已终止订阅段的实际终止时刻；当前有效段为 nil。
31		endedAt *time.Time
32	}
33	
34	type eventRecord struct {
35		at     time.Time
36		qty    int64
37		period Month
38	}
39	
40	type billRecord struct {
41		bill Bill
42	}
43	
44	type paymentRecord struct {
45		period Month
46		amount int64
47		// balance 与 settled 是本笔付款首次成功登记完成时账单的余额与付清状态。
48		// 完全相同的重报原样返回该历史结果，不随后续付款或账单当前状态变化。
49		balance int64
50		settled bool
51	}
52	
53	type account struct {
54		id       string
55		sub      *subRecord
56		history  []*subRecord
57		events   map[string]eventRecord
58		usage    map[Month]int64
59		bills    map[Month]*billRecord
60		payments map[string]paymentRecord
61	}
62	
63	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
64	func NewService() *Service {
65		return NewServiceWithClock(time.Now)
66	}
67	
68	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
69	func NewServiceWithClock(now func() time.Time) *Service {
70		if now == nil {
71			now = time.Now
72		}
73		return &Service{
74			now:      now,
75			accounts: make(map[string]*account),
76			plans:    make(map[string]Plan),
77		}
78	}
79	
80	func (s *Service) nowUTC() time.Time {
81		return s.now().UTC()
82	}
83	
84	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
85	func (s *Service) CreateAccount(id string) error {
86		if id == "" {
87			return invalidf("account id is empty")
88		}
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		if _, ok := s.accounts[id]; ok {
92			return ErrAccountExists
93		}
94		s.accounts[id] = &account{
95			id:       id,
96			events:   make(map[string]eventRecord),
97			usage:    make(map[Month]int64),
98			bills:    make(map[Month]*billRecord),
99			payments: make(map[string]paymentRecord),
100		}
101		return nil
102	}
103	
104	func validatePlan(p Plan) error {
105		if p.ID == "" {
106			return invalidf("plan id is empty")
107		}
108		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
109			return invalidf("plan %q has negative amount or quantity", p.ID)
110		}
111		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
112			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
113		}
114		return nil
115	}
116	
117	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
118	func (s *Service) CreatePlan(p Plan) error {
119		if err := validatePlan(p); err != nil {
120			return err
121		}
122		s.mu.Lock()
123		defer s.mu.Unlock()
124		if _, ok := s.plans[p.ID]; ok {
125			return ErrPlanExists
126		}
127		s.plans[p.ID] = p
128		return nil
129	}
130	
131	// UpdatePlan 更新套餐当前条件。只影响之后开通的订阅，
132	// 已开通订阅继续使用开通时保存的快照。
133	func (s *Service) UpdatePlan(p Plan) error {
134		if err := validatePlan(p); err != nil {
135			return err
136		}
137		s.mu.Lock()
138		defer s.mu.Unlock()
139		if _, ok := s.plans[p.ID]; !ok {
140			return ErrPlanNotFound
141		}
142		s.plans[p.ID] = p
143		return nil
144	}
145	
146	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
147	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
148	// 首月仍收完整月费并提供完整额度。
149	//
150	// activatedAt 可以晚于当前时刻，即提前登记一份尚未生效的订阅：登记会被保留，
151	// 但在实际开通时刻到达前 Status 的 Subscribed 为 false、CurrentTerms 为零值，
152	// 也没有待换套餐安排与待取消终止时刻；此期间再次开通仍返回
153	// ErrSubscriptionExists，安排换套餐、登记取消返回 ErrSubscriptionNotActivated。
154	// 判断以实际开通时刻为界（按同一瞬间比较，带时区的开通时间结果一致），不按
155	// 开通月份提前生效；到达开通时刻后查询即显示有效订阅与登记时保存的完整套餐
156	// 条件快照，等待期间修改套餐定义不改变该快照。
157	//
158	// 订阅终止（按月取消到达终止时刻）后可用本入口重新开通：activatedAt 不得早于
159	// 上一段订阅的终止时刻；重新开通保存当时的套餐条件，当月仍收完整月费、给完整
160	// 额度。重新开通不重置账户内事件与付款标识，也不清除旧欠费。同样允许登记未来
161	// 的重新开通时刻：旧订阅已结束、新订阅尚未开始的间隔中查询不显示任何生效套餐，
162	// 历史用量与账单继续可查。
163	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
164		if accountID == "" {
165			return invalidf("account id is empty")
166		}
167		if planID == "" {
168			return invalidf("plan id is empty")
169		}
170		if activatedAt.IsZero() {
171			return invalidf("activated at is zero")
172		}
173		s.mu.Lock()
174		defer s.mu.Unlock()
175		acc, ok := s.accounts[accountID]
176		if !ok {
177			return ErrAccountNotFound
178		}
179		now := s.nowUTC()
180		// 与其他入口保持一致：先让已到期的换套餐/取消落入历史。
181		s.settleLocked(acc, now)
182		plan, ok := s.plans[planID]
183		if !ok {
184			return ErrPlanNotFound
185		}
186		if acc.sub != nil {
187			return ErrSubscriptionExists
188		}
189		activated := activatedAt.UTC()
190		// 重新开通时刻不得早于上一段订阅的终止时刻。
191		if n := len(acc.history); n > 0 {
192			if activated.Before(*acc.history[n-1].endedAt) {
193				return ErrResubscribeBeforeEnd
194			}
195		}
196		acc.sub = &subRecord{
197			planID:      planID,
198			terms:       termsOf(plan),
199			activatedAt: activated,
200			termsHistory: []termsEntry{{
201				effective: MonthOf(activated),
202				terms:     termsOf(plan),
203			}},
204		}
205		return nil
206	}
207	
208	// nextMonth 返回 period 的下一个 UTC 自然月。
209	func nextMonth(period Month) Month {
210		return MonthOf(period.End())
211	}
212	
213	// settleLocked 让当前订阅段中已到生效时刻的换套餐安排落入条件历史，
214	// 并在到达取消终止时刻时把当前段标记终止、移入 acc.history。
215	// 到达月初零点（或终止时刻）即生效，无需先上报用量或生成账单；即使中间若干月
216	// 没有调用服务，再次进入时也会在此一次性补齐。调用时持有 s.mu。
217	//
218	// 开通时刻尚未到达的订阅段只是提前登记：它尚未生效，既没有已生效的套餐条件，
219	// 也不可能有待换套餐安排或待取消终止时刻，因此在到达开通时刻前不做任何处理，
220	// 尤其不能按开通月份让条件“提前生效”。
221	func (s *Service) settleLocked(acc *account, now time.Time) {
222		sub := acc.sub
223		if sub == nil || now.Before(sub.activatedAt) {
224			return
225		}
226		current := MonthOf(now)
227		for sub.pending != nil && !current.Before(sub.pending.EffectivePeriod) {
228			entry := termsEntry{
229				effective: sub.pending.EffectivePeriod,
230				terms:     sub.pending.Terms,
231			}
232			sub.termsHistory = append(sub.termsHistory, entry)
233			sub.planID = sub.pending.TargetPlanID
234			sub.terms = sub.pending.Terms
235			sub.pending = nil
236		}
237		if sub.cancelEnd != nil && !now.Before(*sub.cancelEnd) {
238			end := *sub.cancelEnd
239			sub.cancelEnd = nil
240			sub.pending = nil
241			sub.endedAt = &end
242			acc.history = append(acc.history, sub)
243			acc.sub = nil
244		}
245	}
246	
247	// activeSegmentAtLocked 返回覆盖时刻 at 的订阅段：activatedAt <= at < end。
248	// 优先检查当前段，再按时间倒序检查历史段。调用时持有 s.mu。
249	func activeSegmentAtLocked(acc *account, at time.Time) *subRecord {
250		if cur := acc.sub; cur != nil && !at.Before(cur.activatedAt) {
251			if cur.cancelEnd == nil || at.Before(*cur.cancelEnd) {
252				return cur
253			}
254		}
255		for i := len(acc.history) - 1; i >= 0; i-- {
256			h := acc.history[i]
257			if !at.Before(h.activatedAt) && at.Before(*h.endedAt) {
258				return h
259			}
260		}
261		return nil
262	}
263	
264	// termsForPeriod 在订阅段 sub 中返回指定账期当时适用的套餐条件快照。
265	// 条件历史按生效月份升序，取不晚于 period 的最后一条；
266	// 这样历史账单始终按该账期条件计算，不受后续换套餐影响。
267	func termsForPeriod(sub *subRecord, period Month) PlanTerms {
268		t := sub.termsHistory[0].terms
269		for _, e := range sub.termsHistory {
270			if period.Before(e.effective) {
271				break
272			}
273			t = e.terms
274		}
275		return t
276	}
277	
278	// segmentForBillingLocked 返回账期 period 应使用的订阅段：
279	// 该订阅段在该账期内确有覆盖（开通当月计入，终止当月不计入）。
280	// 完全无订阅覆盖的月份返回 nil。调用时持有 s.mu。
281	func segmentForBillingLocked(acc *account, period Month) *subRecord {
282		if cur := acc.sub; cur != nil && !period.Before(MonthOf(cur.activatedAt)) {
283			return cur
284		}
285		for i := len(acc.history) - 1; i >= 0; i-- {
286			h := acc.history[i]
287			if period.Before(MonthOf(h.activatedAt)) {
288				continue
289			}
290			if period.Before(MonthOf(*h.endedAt)) {
291				return h
292			}
293		}
294		return nil
295	}
