114		// 修改套餐不改变已开通订阅的计费条件，但影响新订阅。
115		if err := s.UpdatePlan(Plan{ID: "p", MonthlyFee: 999, IncludedUnits: 1, OveragePrice: 9, TaxRateBasisPoints: 2000}); err != nil {
116			t.Fatalf("update: %v", err)
117		}
118		if err := s.Subscribe("b", "p", utc(2026, 1, 16, 0, 0)); err != nil {
119			t.Fatalf("subscribe b: %v", err)
120		}
121		ta := s.subTerms("a")
122		tb := s.subTerms("b")
123		if ta != (PlanTerms{PlanID: "p", MonthlyFee: 100, IncludedUnits: 10, OveragePrice: 5, TaxRateBasisPoints: 1000}) {
124			t.Fatalf("a terms changed: %+v", ta)
125		}
126		if tb.MonthlyFee != 999 || tb.IncludedUnits != 1 || tb.OveragePrice != 9 || tb.TaxRateBasisPoints != 2000 {
127			t.Fatalf("b terms not updated: %+v", tb)
