146		}
147		if err := s.Subscribe("a", "p", utc(2026, 1, 15, 8, 0)); err != nil {
148			t.Fatal(err)
149		}
150		if err := s.Subscribe("b", "p", utc(2026, 1, 15, 8, 0)); err != nil {
151			t.Fatal(err)
152		}
153	
154		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "x", At: utc(2026, 1, 15, 7, 59), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
155			t.Fatalf("before activation: %v", err)
156		}
157		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "x", At: clk.get().Add(time.Second), Quantity: 1}); !errors.Is(err, ErrEventInFuture) {
158			t.Fatalf("future: %v", err)
159		}
160		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "x", At: utc(2026, 1, 15, 9, 0), Quantity: -1}); !errors.Is(err, ErrInvalidArgument) {
161			t.Fatalf("negative qty: %v", err)
162		}
163		if _, err := s.RecordEvent(Event{AccountID: "ghost", EventID: "x", At: utc(2026, 1, 15, 9, 0), Quantity: 1}); !errors.Is(err, ErrAccountNotFound) {
164			t.Fatalf("missing account: %v", err)
165		}
166	
167		ev = Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 15, 9, 0), Quantity: 3}
168		r1, err := s.RecordEvent(ev)
169		if err != nil || !r1.Accepted || r1.Period != jan(2026) {
170			t.Fatalf("first accept: %+v %v", r1, err)
171		}
172		r2, err := s.RecordEvent(ev)
173		if err != nil || r2.Accepted {
174			t.Fatalf("identical replay must not accumulate: %+v %v", r2, err)
175		}
176		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: ev.At, Quantity: 4}); !errors.Is(err, ErrEventConflict) {
177			t.Fatalf("qty conflict: %v", err)
178		}
179		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: ev.At.Add(time.Second), Quantity: 3}); !errors.Is(err, ErrEventConflict) {
180			t.Fatalf("time conflict: %v", err)
181		}
182		// 冲突不改变累计用量。
183		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 3 {
184			t.Fatalf("usage after conflicts = %d", u.Total)
185		}
