187		// 不同账户可复用事件标识，且互不影响。
188		clk.t = utc(2026, 1, 16, 12, 0)
189		if _, err := s.RecordEvent(Event{AccountID: "b", EventID: "e1", At: utc(2026, 1, 16, 0, 0), Quantity: 7}); err != nil {
190			t.Fatalf("cross-account id: %v", err)
191		}
192		if u, _ := s.MonthlyUsage("b", jan(2026)); u.Total != 7 {
193			t.Fatalf("b usage = %d", u.Total)
194		}
195	
196		// 事件按发生时刻归账期：1 月 31 日深夜发生、2 月上报仍归入 1 月。
197		clk.t = utc(2026, 2, 1, 10, 0)
198		r3, err := s.RecordEvent(Event{AccountID: "a", EventID: "late", At: utc(2026, 1, 31, 23, 59), Quantity: 2})
199		if err != nil || r3.Period != jan(2026) {
200			t.Fatalf("late Jan event: %+v %v", r3, err)
201		}
202		// UTC 月初属于新一期。
203		r4, err := s.RecordEvent(Event{AccountID: "a", EventID: "feb1", At: utc(2026, 2, 1, 0, 0), Quantity: 4})
204		if err != nil || r4.Period != feb(2026) {
205			t.Fatalf("Feb boundary: %+v %v", r4, err)
206		}
207	
208		// 出账后：新事件拒绝，同标识重报仍成功。
209		bill, err := s.CreateBill("a", jan(2026))
210		if err != nil {
211			t.Fatal(err)
212		}
213		if bill.TotalUsage != 5 {
214			t.Fatalf("jan total = %d, want 5", bill.TotalUsage)
215		}
216		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "new-after-bill", At: utc(2026, 1, 20, 0, 0), Quantity: 1}); !errors.Is(err, ErrMonthBilled) {
217			t.Fatalf("new event after billed: %v", err)
218		}
219		if r, err := s.RecordEvent(ev); err != nil || r.Accepted {
220			t.Fatalf("replay after billed must succeed: %+v %v", r, err)
221		}
